document.addEventListener('DOMContentLoaded',()=>{const catalog=['Praia Grande','Praia do Bonfim','Ilha de Gipóia','Ilha Cataguás','Ilha Grande','Vila do Abraão','Cachoeira da Feiticeira','Pico do Papagaio','Convento do Carmo','Museu de Arte Sacra','Lagoa Azul','Praia de Lopes Mendes','Praia do Caxadaço','Praia de Dois Rios','Passeio de escuna'];let i=0;const t=document.querySelector('#title'),c=document.querySelector('#counter');document.querySelectorAll('.actions button').forEach(b=>b.addEventListener('click',()=>{i=(i+1)%catalog.length;t.textContent=catalog[i];c.textContent=`${i+1} de ${catalog.length} lugares`}));});
